-- Migração segura: acrescenta O Que é o Espiritismo (100 questões).
-- Preserva as questões existentes; ignora enunciados que já estejam cadastrados.
BEGIN;

ALTER TABLE public.questions DROP CONSTRAINT IF EXISTS questions_book_check;
ALTER TABLE public.questions ADD CONSTRAINT questions_book_check
  CHECK (book IN ('livro_espiritos','evangelho','ceu_inferno','genese','livro_mediuns','obras_postumas','nosso_lar','os_mensageiros','o_que_e_espiritismo'));

ALTER TABLE public.questions DROP CONSTRAINT IF EXISTS questions_difficulty_check;
ALTER TABLE public.questions ADD CONSTRAINT questions_difficulty_check
  CHECK (difficulty IN ('facil','medio','dificil','expert'));

-- Alinha a sequência antes de inserir, evitando colisões com códigos já existentes.
SELECT setval('public.questions_code_seq',
  COALESCE((SELECT MAX(code) FROM public.questions), 0) + 1, false);

INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
SELECT
  'o_que_e_espiritismo', q.statement, q.option_a, q.option_b, q.option_c,
  q.option_d, q.option_e, q.correct_option, q.explanation, q.reference,
  q.difficulty, q.active
FROM jsonb_to_recordset($questions$[{"code":801,"statement":"Segundo a biografia escrita por Henri Sausse em 'O Que é o Espiritismo', em que cidade e data nasceu Allan Kardec?","option_a":"Em Lyon, a 3 de outubro de 1804.","option_b":"Em Paris, a 18 de abril de 1804.","option_c":"Em Bordeaux, a 31 de março de 1805.","option_d":"Em Tours, a 3 de novembro de 1803.","option_e":"Em Genebra, a 15 de agosto de 1804.","correct_option":"A","explanation":"Henri Sausse registra que Allan Kardec nasceu em Lyon a 3 de outubro de 1804, recebendo o nome civil de Hippolyte Léon Denizard Rivail.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":802,"statement":"Qual era o nome civil completo do Codificador do Espiritismo antes de adotar o pseudônimo Allan Kardec?","option_a":"Jean-Baptiste Léon Fortier Rivail.","option_b":"Hippolyte Léon Denizard Rivail.","option_c":"Pierre-Paul Didier Baudin.","option_d":"Camille Nicolas Denizard Flammarion.","option_e":"Henri Léon Sausse Rivail.","correct_option":"B","explanation":"Filho do magistrado Jean-Baptiste Antoine Rivail, o Codificador chamava-se no registro civil Hippolyte Léon Denizard Rivail.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":803,"statement":"Em qual instituição suíça o jovem Denizard Rivail realizou seus estudos pedagógicos sob a direção de um célebre educador?","option_a":"Na Academia de Genebra, sob a direção de Jean-Jacques Rousseau.","option_b":"No Colégio de Lausanne, dirigido pelo pastor Charles Wagner.","option_c":"No Instituto de Yverdon, dirigido pelo célebre professor Pestalozzi.","option_d":"No Liceu de Zurique, dirigido por Heinrich Lavater.","option_e":"Na Escola Politécnica de Berna, sob orientação de Girard.","correct_option":"C","explanation":"Seus pais enviaram-no para o famoso Instituto de Yverdon, na Suíça, dirigido por Johann Heinrich Pestalozzi, de quem se tornou discípulo e colaborador.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":804,"statement":"Com quem o professor Hippolyte Léon Denizard Rivail se casou em 6 de fevereiro de 1832?","option_a":"Com Ermance Dufaux.","option_b":"Com Caroline e Julie Baudin.","option_c":"Com Ruth Japhet.","option_d":"Com Amélie Gabrielle Boudet.","option_e":"Com Madame Plainemaison.","correct_option":"D","explanation":"Em 1832, o professor Rivail desposou Amélie Gabrielle Boudet, culta professora que foi sua dedicada companheira e colaboradora durante toda a vida.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":805,"statement":"Em que ano, segundo Henri Sausse, o professor Rivail ouviu falar pela primeira vez das mesas girantes por meio do magnetizador Sr. Fortier?","option_a":"Em 1848, logo após os fenômenos de Hydesville.","option_b":"Em 1850, durante um congresso de magnetismo em Lyon.","option_c":"Em 1852, na Academia Real de Ciências de Arras.","option_d":"Em 1857, pouco antes de publicar O Livro dos Espíritos.","option_e":"Em 1854, quando o Sr. Fortier lhe relatou que as mesas não apenas giravam, mas também falavam.","correct_option":"E","explanation":"Foi em 1854 que o Sr. Fortier, magnetizador de suas relações, falou-lhe pela primeira vez das mesas girantes e das comunicações obtidas por batidas.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":806,"statement":"Na casa de quem, em maio de 1855, o professor Rivail presenciou pela primeira vez o fenômeno das mesas que giravam, saltavam e corriam?","option_a":"Na casa da Sra. Plainemaison, na rua Grange-Batelière.","option_b":"Na residência de Camille Flammarion, no Observatório de Paris.","option_c":"No salão literário do livreiro Didier, no Palais-Royal.","option_d":"No gabinete médico do Dr. Paul Bert.","option_e":"No Instituto Técnico da rua de Sèvres.","correct_option":"A","explanation":"Em maio de 1855, acompanhado do Sr. Pottié, Rivail assistiu pela primeira vez às experiências de mesas girantes e escrita em ardósia na casa da Sra. Plainemaison.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":807,"statement":"Na casa de qual família o professor Rivail iniciou seus estudos regulares e metódicos das comunicações psicográficas por meio de duas jovens médiuns?","option_a":"Na casa da família Fortier.","option_b":"Na casa da família Baudin, com as jovens Caroline e Julie.","option_c":"Na casa da família Sausse, em Lyon.","option_d":"Na casa da família Delanne, em Paris.","option_e":"Na casa da família Lachâtre, em Toulon.","correct_option":"B","explanation":"Foi nas reuniões semanais na casa da família Baudin, onde escreviam na cesta-pião as jovens médiuns Srta. Julie e Srta. Caroline Baudin, que Rivail iniciou seus estudos sérios.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":808,"statement":"Por meio de qual médium sonâmbula o professor Rivail fez a verificação e revisão completa dos cinquenta cadernos que deram origem a 'O Livro dos Espíritos'?","option_a":"Sra. Plainemaison.","option_b":"Sra. Amélie Boudet.","option_c":"Srta. Ruth Japhet.","option_d":"Srta. Aline Carlotti.","option_e":"Sra. d'Espérance.","correct_option":"C","explanation":"Cerca de cinquenta cadernos confiados pelos Srs. Carlotti, René Taillandier, Tiedeman-Manthese e Sardou foram coordenados e revistos com o concurso da médium Srta. Japhet.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"dificil","active":true},{"code":809,"statement":"Em que data veio a lume a primeira edição de 'O Livro dos Espíritos', marco inaugural da Codificação Espírita?","option_a":"1 de janeiro de 1858.","option_b":"3 de outubro de 1856.","option_c":"31 de março de 1857.","option_d":"18 de abril de 1857.","option_e":"15 de agosto de 1859.","correct_option":"D","explanation":"A primeira edição de O Livro dos Espíritos foi publicada em Paris, pela livraria Dentu, no Palais-Royal, em 18 de abril de 1857.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":810,"statement":"Por que o professor Rivail decidiu assinar as obras espíritas com o pseudônimo Allan Kardec?","option_a":"Para ocultar sua nacionalidade francesa diante das autoridades eclesiásticas.","option_b":"Porque seu editor exigiu um nome de sonoridade inglesa para ampliar as vendas.","option_c":"Por imposição da Academia Real de Ciências de Arras.","option_d":"Para homenagear seu antigo mestre suíço Pestalozzi.","option_e":"Para não confundir sua obra espírita, fruto do ensino dos Espíritos, com seus conhecidos livros pedagógicos assinados com o nome civil.","correct_option":"E","explanation":"Sendo seu nome civil muito conhecido pelas obras didáticas e gramaticais, adotou o nome Allan Kardec — que seu Espírito protetor revelou ter sido seu em existência anterior entre os druidas — para distinguir a obra espírita.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"dificil","active":true},{"code":811,"statement":"Em que datas foram fundadas por Allan Kardec, respectivamente, a 'Revista Espírita' e a 'Sociedade Parisiense de Estudos Espíritas'?","option_a":"1º de janeiro de 1858 e 1º de abril de 1858.","option_b":"18 de abril de 1857 e 1º de janeiro de 1858.","option_c":"3 de outubro de 1858 e 25 de dezembro de 1858.","option_d":"15 de maio de 1857 e 18 de abril de 1859.","option_e":"1º de março de 1859 e 31 de março de 1860.","correct_option":"A","explanation":"Allan Kardec lançou o primeiro número da Revista Espírita em 1º de janeiro de 1858 e fundou regularmente a Sociedade Parisiense de Estudos Espíritas em 1º de abril de 1858.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":812,"statement":"Em que data e por qual causa orgânica desencarnou Allan Kardec em Paris, aos 64 anos de idade?","option_a":"Em 18 de abril de 1869, vítima de pneumonia aguda.","option_b":"Em 31 de março de 1869, fulminado pela ruptura de um aneurisma.","option_c":"Em 2 de novembro de 1869, em decorrência de febre tifoide.","option_d":"Em 3 de outubro de 1868, após um acidente vascular em viagem a Lyon.","option_e":"Em 15 de janeiro de 1870, por insuficiência renal crônica.","correct_option":"B","explanation":"Em 31 de março de 1869, enquanto preparava a mudança da sede para a rua e passagem Sainte-Anne e entregava um exemplar da Revista Espírita a um caixeiro de livraria, tombou fulminado pela ruptura de um aneurisma.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":813,"statement":"Qual célebre astrônomo francês pronunciou um discurso memorável à beira do túmulo de Allan Kardec, chamando-o de 'o bom senso encarnado'?","option_a":"Urbain Le Verrier.","option_b":"François Arago.","option_c":"Camille Flammarion.","option_d":"Pierre-Simon Laplace.","option_e":"Jean-Baptiste Biot.","correct_option":"C","explanation":"No sepultamento de Allan Kardec, o astrônomo Camille Flammarion proferiu vibrante alocução, definindo o Codificador como 'o bom senso encarnado' e ressaltando o caráter científico do Espiritismo.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":814,"statement":"Qual inscrição sintetizadora da lei de evolução encontra-se gravada no frontão do dólmen de Allan Kardec no cemitério do Père-Lachaise?","option_a":"A fé inabalável é apenas aquela que pode encarar a razão face a face.","option_b":"Fora da caridade não há salvação para o Espírito imortal.","option_c":"Os mortos não morrem: apenas mudam de morada na casa do Pai.","option_d":"Nascer, morrer, renascer ainda e progredir sempre, tal é a lei.","option_e":"Trabalho, solidariedade e tolerância constituem o lema do espírita.","correct_option":"D","explanation":"No alto do monumento druídico (dólmen) no cemitério do Père-Lachaise acha-se gravado o postulado fundamental: 'Nascer, morrer, renascer ainda e progredir sempre, tal é a lei'.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"facil","active":true},{"code":815,"statement":"Segundo o Preâmbulo de 'O Que é o Espiritismo', qual foi o objetivo principal de Allan Kardec ao publicar este livro sumário?","option_a":"Substituir definitivamente a leitura de O Livro dos Espíritos e de O Livro dos Médiuns.","option_b":"Criar um ritual litúrgico obrigatório para todas as sociedades espíritas da França.","option_c":"Reunir apenas relatos de fenômenos físicos extraordinários para entreter o público.","option_d":"Combater pessoalmente os sacerdotes e cientistas que atacavam sua reputação.","option_e":"Oferecer um resumo sintético dos princípios da Doutrina e responder às principais objeções para quem deseja compreendê-la rapidamente.","correct_option":"E","explanation":"No Preâmbulo, Kardec explica que publicou este resumo para dar em poucas palavras uma ideia exata do Espiritismo, fornecendo os pontos cardeais da ciência e respondendo às objeções mais comuns.","reference":"O Que é o Espiritismo - Preâmbulo","difficulty":"medio","active":true},{"code":816,"statement":"No Capítulo I de 'O Que é o Espiritismo' ('Pequena conferência espírita'), quais são os três interlocutores com quem o Adeptos dialoga sucessivamente?","option_a":"O Crítico, o Cético e o Padre.","option_b":"O Médico, o Juiz e o Filósofo.","option_c":"O Materialista, o Cientista e o Pastor.","option_d":"O Jornalista, o Magnetizador e o Bispo.","option_e":"O Professor, o Ateo e o Monge.","correct_option":"A","explanation":"O Capítulo I é dividido em três diálogos: o Primeiro Diálogo com O Crítico, o Segundo Diálogo com O Cético e o Terceiro Diálogo com O Padre.","reference":"O Que é o Espiritismo - Cap. I, Pequena conferência espírita","difficulty":"facil","active":true},{"code":817,"statement":"No Primeiro Diálogo ('O Crítico'), que diferença fundamental o Visitante aponta entre a atitude do Crítico e a do Cético?","option_a":"O Crítico crê nos Espíritos, enquanto o Cético acredita apenas em anjos.","option_b":"O Cético duvida, mas busca esclarecer-se; o Crítico julga sem conhecer e procura ridicularizar aquilo que não estudou.","option_c":"O Crítico realiza experiências práticas, enquanto o Cético apenas escreve panfletos.","option_d":"O Cético é sempre inimigo da Ciência, ao passo que o Crítico defende as academias.","option_e":"Não há diferença alguma, pois ambos negam a existência de Deus.","correct_option":"B","explanation":"Kardec mostra no diálogo que o Crítico condena a priori e usa a zombaria sem haver lido nem observado nada, ao passo que o Cético sincero apresenta dúvidas racionais e deseja instruir-se.","reference":"O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico","difficulty":"medio","active":true},{"code":818,"statement":"No Primeiro Diálogo, quando o Crítico alega que os sábios e as academias oficiais condenaram o Espiritismo, que exemplos históricos o espírita lhe recorda?","option_a":"A aceitação imediata do telégrafo óptico e da imprensa em toda a Europa.","option_b":"A aprovação unânime das descobertas de Newton pela Igreja de Roma.","option_c":"A rejeição inicial de grandes descobertas científicas, como o movimento da Terra por Galileu e a aplicação do vapor por Fulton.","option_d":"O apoio financeiro concedido por Napoleão aos primeiros barcos a vapor.","option_e":"A criação das universidades medievais pelos escolásticos.","correct_option":"C","explanation":"Kardec lembra ao Crítico que corporações sábias também rejeitaram ou zombaram de Galileu, de Colombo e de Fulton com o barco a vapor, provando que a verdade independe de decretos acadêmicos.","reference":"O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico","difficulty":"medio","active":true},{"code":819,"statement":"Segundo argumenta Kardec no Primeiro Diálogo com o Crítico, qual foi o efeito prático das zombarias e dos ataques da imprensa burlesca contra o Espiritismo?","option_a":"Reduziram drasticamente o número de adeptos nas grandes capitais.","option_b":"Forçaram o fechamento temporário da Sociedade Parisiense de Estudos Espíritas.","option_c":"Impediram a tradução das obras espíritas para outros idiomas europeus.","option_d":"Despertaram a atenção do público, levando milhares de pessoas a examinar a Doutrina e aumentando o número de adeptos.","option_e":"Fizeram com que os médiuns abandonassem a psicografia pelo receio do ridículo.","correct_option":"D","explanation":"Kardec demonstra que as críticas levianas funcionaram como propaganda involuntária: aguando a curiosidade pública, fizeram com que pessoas sérias lessem as obras e se tornassem espíritas.","reference":"O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico","difficulty":"dificil","active":true},{"code":820,"statement":"Ao responder ao Crítico sobre os casos de charlatanismo e exploração financeira das manifestações, qual é a posição firme da Doutrina Espírita?","option_a":"Tolera a cobrança moderada quando o médium é comprovadamente pobre.","option_b":"Permite sessões pagas desde que a renda seja destinada a hospitais.","option_c":"Autoriza os médiuns profissionais a cobrarem consultas particulares.","option_d":"Reconhece que apenas os fenômenos de efeitos físicos podem ser remunerados.","option_e":"Repudia formalmente qualquer exploração mercantil da mediunidade, declarando que o verdadeiro Espiritismo jamais faz de suas manifestações objeto de lucro.","correct_option":"E","explanation":"Kardec enfatiza que o Espiritismo sério condena de modo absoluto os espetáculos pagos e o comércio da mediunidade, não podendo a Ciência verdadeira responder pelos abusos dos charlatães.","reference":"O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico","difficulty":"dificil","active":true},{"code":821,"statement":"No início do Segundo Diálogo ('O Cético'), como o espírita recebe a declaração do Visitante de que não crê nos Espíritos, mas deseja compreender a questão?","option_a":"Com simpatia e respeito, pois a dúvida sincera de quem procura instruir-se merece explicação racional.","option_b":"Com indignação, recusando-se a conversar com quem ainda não tem fé.","option_c":"Exigindo que o visitante faça antes um juramento de adesão religiosa.","option_d":"Cobrando uma taxa de matrícula no curso preparatório da Sociedade.","option_e":"Aconselhando-o a desistir, pois a fé espírita só se obtém por graça mística.","correct_option":"A","explanation":"Kardec acolhe o Cético com estima, esclarecendo que o Espiritismo não exige fé cega, mas convida ao exame sério, metódico e livre de ideias preconcebidas.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":822,"statement":"No Segundo Diálogo ('O Cético'), como Allan Kardec define de modo claro e direto o que são os Espíritos?","option_a":"São seres angélicos criados à parte da humanidade e que jamais encarnaram.","option_b":"São as próprias almas dos homens que viveram na Terra ou em outros mundos, despojadas de seu envoltório corporal.","option_c":"São emanações magnéticas inconscientes produzidas pelo cérebro dos médiuns.","option_d":"São divindades secundárias encarregadas de governar as forças da natureza.","option_e":"São alucinações coletivas provocadas pelo fluido nervoso dos assistentes.","correct_option":"B","explanation":"Kardec explica ao Cético que os Espíritos não são seres abstratos nem uma criação nova: são simplesmente as almas dos homens após a morte do corpo físico.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":823,"statement":"Para demonstrar ao Cético a existência da alma independente da matéria, que argumento fundamental o espírita utiliza?","option_a":"A tradição mitológica dos povos gregos e romanos.","option_b":"A autoridade infalível dos concílios medievais.","option_c":"O fato de que o pensamento, a vontade e o livre-arbítrio são propriedades inteligentes que não podem ser produzidas pela matéria bruta.","option_d":"A semelhança anatômica entre o sistema nervoso humano e o dos vegetais.","option_e":"O cálculo matemático da distância entre as estrelas fixas.","correct_option":"C","explanation":"Todo efeito inteligente há de ter uma causa inteligente; como a matéria por si mesma é inerte e desprovida de inteligência, o pensamento humano prova a presença de um princípio espiritual.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":824,"statement":"Segundo explica Kardec ao Cético, de quantos elementos essenciais se compõe o homem encarnado?","option_a":"De dois elementos apenas: o corpo carnal e o fluido elétrico.","option_b":"De quatro elementos: terra, água, ar e fogo.","option_c":"De um único elemento material capaz de produzir o pensamento.","option_d":"De três elementos: o corpo (ser material), a alma (Espírito encarnado) e o perispírito (envoltório semimaterial que une a alma ao corpo).","option_e":"De cinco corpos astrais independentes entre si.","correct_option":"D","explanation":"Kardec apresenta a constituição ternária do homem: 1º o corpo físico; 2º a alma ou Espírito; 3º o perispírito, laço fluídico semimaterial que serve de intermediário entre ambos.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":825,"statement":"Quando o Cético pergunta por que uma mesa se move ou responde por pancadas nas sessões de efeitos físicos, o que o espírita lhe esclarece?","option_a":"Que a madeira adquire inteligência própria ao ser magnetizada pelos presentes.","option_b":"Que o movimento resulta exclusivamente da eletricidade terrestre acumulada no móvel.","option_c":"Que todos os movimentos de mesas são produzidos por mecanismos ocultos sob o soalho.","option_d":"Que os Espíritos se transformam materialmente na própria estrutura da mesa.","option_e":"Que a mesa é apenas um instrumento passivo movido pelo Espírito, que combina parte de seu perispírito com o fluido animalizado do médium.","correct_option":"E","explanation":"A mesa não pensa nem tem músculos: o Espírito utiliza o fluido próprio do médium combinado ao fluido universal e ao seu perispírito para imprimir movimento ao objeto e dar sinais convencionados.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"medio","active":true},{"code":826,"statement":"No Segundo Diálogo, por que o uso das mesas falantes e das cestas foi gradualmente substituído pela escrita direta com a mão do médium (psicografia)?","option_a":"Porque a escrita manual direta é o meio mais simples, rápido e cômodo de comunicação, dispensando aparelhos acessórios.","option_b":"Porque as mesas deixaram de girar após o ano de 1856 em toda a Europa.","option_c":"Porque a polícia francesa proibiu a fabricação de cestas-pião e pranchetas.","option_d":"Porque os Espíritos Superiores só conseguem se comunicar por meio de mesas pesadas.","option_e":"Porque a escrita direta impede totalmente a manifestação de Espíritos levianos.","correct_option":"A","explanation":"As mesas, cestas e pranchetas eram apenas apêndices do lápis; compreendeu-se logo que o Espírito podia atuar diretamente sobre o braço e a mão do médium, tornando a comunicação muito mais rápida.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"medio","active":true},{"code":827,"statement":"No diálogo com o Cético, qual é a posição do Espiritismo a respeito do Magnetismo e do Sonambulismo?","option_a":"Considera o magnetismo uma superstição medieval sem qualquer base real.","option_b":"Reconhece-os como ciências irmãs que prepararam o caminho ao demonstrar a ação dos fluidos e a independência da alma.","option_c":"Afirma que o magnetizador só cura quando pronuncia fórmulas cabalísticas.","option_d":"Sustenta que todo médium psicógrafo precisa antes ser magnetizado por um médico.","option_e":"Declara que o fluido magnético destrói a faculdade mediúnica.","correct_option":"B","explanation":"Kardec explica que o magnetismo preparou o caminho do Espiritismo, pois o estudo do fluido magnético e da clarividência sonambúlica já demonstrava a ação da alma fora dos sentidos corpóreos.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":828,"statement":"Que fatos comprovam ao Cético que as comunicações mediúnicas não são simples reflexo das ideias do próprio médium?","option_a":"O fato de o médium usar sempre papel timbrado das sociedades espíritas.","option_b":"A velocidade com que o lápis percorre o papel em linha reta.","option_c":"Comunicações contrárias às opiniões e conhecimentos do médium, em línguas que ele ignora ou até por pessoas analfabetas.","option_d":"O cansaço muscular sentido no braço após duas horas de escrita.","option_e":"A presença obrigatória de sete testemunhas diplomadas na sala.","correct_option":"C","explanation":"O Espírito frequentemente trata de assuntos estranhos aos estudos do médium, contradiz suas ideias preconcebidas, revela fatos desconhecidos e por vezes escreve em idiomas que o médium desconhece.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":829,"statement":"Quando o Cético pergunta se basta morrer para que o Espírito saiba tudo e possua toda a sabedoria, o que Kardec responde?","option_a":"Sim, pois a morte rasga imediatamente todos os véus do universo.","option_b":"Sim, desde que o falecido tenha recebido os sacramentos antes de partir.","option_c":"Não, porque após a morte todos os Espíritos perdem a memória para sempre.","option_d":"Não; a morte física não opera transformação miraculosa: o Espírito conserva o grau intelectual e moral que tinha em vida, progredindo gradualmente.","option_e":"Apenas os cientistas conservam a inteligência no mundo espiritual.","correct_option":"D","explanation":"Ao deixar o corpo, o homem não se torna instantaneamente sábio nem virtuoso; há no mundo invisível Espíritos de todos os graus de saber e de moralidade.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":830,"statement":"Por que os Espíritos não vêm revelar tesouros ocultos, fórmulas para enriquecer sem trabalho ou invenções prontas para especulação financeira?","option_a":"Porque desconhecem o valor das moedas modernas.","option_b":"Porque estão proibidos de observar a superfície material da Terra.","option_c":"Porque apenas os Espíritos zombeteiros conhecem onde estão os tesouros.","option_d":"Porque perderam toda a capacidade de raciocínio prático ao desencarnar.","option_e":"Porque a lei de Deus impõe ao homem o progresso pelo trabalho e pela pesquisa própria, e os bons Espíritos não servem à cupidez nem ao orgulho.","correct_option":"E","explanation":"Os Espíritos Superiores auxiliam o progresso moral e intelectual da humanidade, mas não poupam ao homem o esforço do trabalho; quem busca os Espíritos por interesse material torna-se joguete de mistificadores.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":831,"statement":"No Segundo Diálogo, que resposta o espírita dá à objeção de que o estudo do Espiritismo produziria a loucura?","option_a":"O Espiritismo verdadeiro, longe de produzir a loucura, previne-a e consola as aflições pela fé raciocinada na vida futura e na justiça divina.","option_b":"Admite que metade dos médiuns acaba perdendo a razão após alguns anos.","option_c":"Recomenda que apenas médicos psiquiatras estudem as obras da Codificação.","option_d":"Afirma que a loucura é sempre um castigo físico incurável sem relação com o cérebro.","option_e":"Reconhece que qualquer estudo filosófico ou religioso destrói o sistema nervoso.","correct_option":"A","explanation":"Qualquer ideia exagerada em um cérebro já predisposto e enfraquecido pode desencadear delírios (como na política, nas paixões ou no fanatismo religioso), mas o estudo calmo e racional do Espiritismo fortalece a alma contra o desespero.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"medio","active":true},{"code":832,"statement":"No diálogo com o Cético, por que os fenômenos espíritas não podem ser repetidos à vontade, como uma experiência física ou química de laboratório?","option_a":"Porque os fluidos espirituais evaporam na presença de luz solar.","option_b":"Porque os Espíritos são seres livres e inteligentes, e não máquinas nem reagentes químicos submetidos ao capricho dos observadores.","option_c":"Porque os médiuns perdem suas faculdades diante de mais de três pessoas.","option_d":"Porque a gravidade terrestre anula o perispírito durante o dia.","option_e":"Porque as leis civis proíbem experiências científicas com médiuns.","correct_option":"B","explanation":"As ciências físicas operam sobre a matéria inerte que se manipula à vontade; o Espiritismo lida com inteligências livres que têm vontade própria e não se prestam a exigências frívolas de curiosos.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":833,"statement":"Segundo explica Kardec ao Cético, qual foi a utilidade providencial dos fenômenos materiais (mesas girantes e pancadas) no início do Espiritismo?","option_a":"Demonstrar que os Espíritos preferem comunicar-se por objetos de madeira.","option_b":"Substituir definitivamente a imprensa escrita na transmissão dos ensinos morais.","option_c":"Chamar a atenção dos homens pelos sentidos físicos e vencer a incredulidade materialista, servindo de prelúdio ao ensino filosófico.","option_d":"Provar que apenas os Espíritos inferiores podem agir sobre a matéria.","option_e":"Criar uma nova fonte de energia mecânica para a indústria europeia.","correct_option":"C","explanation":"Os fenômenos físicos foram o vestíbulo da Ciência: falavam aos olhos para despertar a atenção de uma geração incrédula, abrindo caminho para as comunicações inteligentes e morais.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":834,"statement":"No Segundo Diálogo, como o espírita explica ao Cético a justiça das desigualdades de aptidões intelectuais e morais que as crianças trazem desde o berço?","option_a":"Pelo acaso genético resultante apenas da alimentação materna.","option_b":"Pelo privilégio arbitrário concedido por Deus a certas almas recém-criadas.","option_c":"Pela influência astrológica da posição dos planetas no instante do parto.","option_d":"Pela preexistência da alma e pela pluralidade das existências (reencarnação), em que cada Espírito traz o patrimônio adquirido em vidas anteriores.","option_e":"Pela transmissão hereditária da própria alma dos pais para os filhos.","correct_option":"D","explanation":"Se Deus criasse almas novas a cada nascimento com aptidões tão desiguais, seria parcial; a reencarnação explica que uns já viveram e progrediram mais do que outros em existências precedentes.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":835,"statement":"Quando o Cético pergunta se o Espírito pode retrogradar e reencarnar no corpo de um animal, o que responde a Doutrina Espírita?","option_a":"Sim, como punição temporária para os grandes criminosos da humanidade.","option_b":"Sim, sempre que o homem se entrega aos instintos puramente sensuais.","option_c":"Depende da decisão dos Espíritos Superiores em cada julgamento.","option_d":"Apenas nas espécies domésticas mais próximas do convívio humano.","option_e":"Não; o progresso do Espírito é contínuo: ele pode estacionar, mas jamais retrograda, sendo a metempsicose nos animais contrária à lei divina.","correct_option":"E","explanation":"Kardec distingue claramente a reencarnação espírita da antiga metempsicose: o Espírito humano nunca volta a ser animal; se estaciona, reencarna em condições humanas de expiação para avançar.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":836,"statement":"No Segundo Diálogo, todas as reencarnações do Espírito ocorrem exclusivamente no planeta Terra?","option_a":"Não; a Terra é apenas um dos numerosos mundos habitados, e as reencarnações ocorrem em diferentes globos conforme o adiantamento do Espírito.","option_b":"Sim, pois a Terra é o único planeta habitado do universo.","option_c":"Sim, porque o perispírito humano não suporta a atmosfera de outros orbes.","option_d":"Não, pois cada Espírito só encarna uma única vez na Terra e nunca mais retorna.","option_e":"Apenas os Espíritos perfeitos reencarnam na Lua e no Sol.","correct_option":"A","explanation":"As diversas existências corporais podem realizar-se na Terra ou em outros mundos materiais mais ou menos adiantados, segundo a máxima evangélica de que 'há muitas moradas na casa de meu Pai'.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":837,"statement":"Ao final do Segundo Diálogo, que tríplice efeito moral produz no homem a convicção profunda das verdades ensinadas pelo Espiritismo?","option_a":"Isolamento monástico, desprezo pela ciência e temor constante da morte.","option_b":"Paciência e resignação nas provas da vida, afastamento do suicídio e prática sincera da caridade e fraternidade.","option_c":"Ambição política, orgulho intelectual e busca de privilégios sociais.","option_d":"Indiferença diante do sofrimento alheio, fatalismo passivo e ociosidade.","option_e":"Crença na salvação exclusiva por fórmulas exteriores e rituais.","correct_option":"B","explanation":"Compreendendo que a vida terrestre é breve estação de aprendizado, o homem encara a morte sem pavor, suporta as vicissitudes com coragem, repele o suicídio e esforça-se no bem.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"medio","active":true},{"code":838,"statement":"No Terceiro Diálogo ('O Padre'), como o espírita responde à afirmação eclesiástica de que apenas o demônio e seus anjos decaídos podem comunicar-se com os homens?","option_a":"Concordando que as almas humanas permanecem adormecidas até o juízo final.","option_b":"Afirmando que os maus Espíritos não existem no plano espiritual.","option_c":"Mostrando que seria absurdo e contrário à bondade de Deus conceder liberdade de ação apenas ao espírito do mal e proibir as boas almas de consolar e instruir os vivos.","option_d":"Dizendo que os Espíritos só se comunicam dentro dos templos consagrados.","option_e":"Alegando que o Antigo e o Novo Testamento jamais mencionam manifestações espirituais.","correct_option":"C","explanation":"Kardec argumenta com lógica irrefutável: se Deus permite que os maus Espíritos tentem os homens, com muito mais razão permite que os bons Espíritos venham ampará-los e encaminhá-los ao bem.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"medio","active":true},{"code":839,"statement":"No Terceiro Diálogo com o Padre, qual é o critério seguro apontado pelo Espiritismo para distinguir se um Espírito comunicante é bom ou mau?","option_a":"O nome famoso ou sagrado com que ele assina a mensagem.","option_b":"A beleza caligráfica da escrita psicografada pelo médium.","option_c":"A intensidade das pancadas ou o peso da mesa que se levanta.","option_d":"A qualidade moral de sua linguagem e de seus conselhos, pois 'reconhece-se a árvore pelo fruto': um Espírito que só ensina a caridade e o bem não pode ser mau.","option_e":"O horário noturno ou diurno em que ocorre a reunião mediúnica.","correct_option":"D","explanation":"Aplicando a máxima de Jesus ('Pelos seus frutos os conhecereis'), Kardec lembra que o demônio não poderia pregar o amor a Deus, o perdão das ofensas, a humildade e a caridade sem destruir seu próprio reino.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"facil","active":true},{"code":840,"statement":"Quando o Padre cita a proibição mosaica de interrogar os mortos (Deuteronômio), que explicação histórica e doutrinária o espírita apresenta?","option_a":"Que Moisés desconhecia totalmente a existência da alma imortal.","option_b":"Que o texto bíblico foi inventado apenas no século XVIII.","option_c":"Que Moisés proibiu apenas a escrita manual, mas permitiu as mesas girantes.","option_d":"Que a lei mosaica só se aplicava aos sacerdotes egípcios e babilônios.","option_e":"Que Moisés reprimiu o abuso supersticioso da adivinhação mercenária e idólatra entre os hebreus, e que essa própria proibição prova que a comunicação com os mortos era real.","correct_option":"E","explanation":"Não se proíbe aquilo que não existe: Moisés vetou a evocação transformada em ofício de adivinhação e comércio supersticioso, ao passo que o Espiritismo condena esses mesmos abusos e busca a edificação moral.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"expert","active":true},{"code":841,"statement":"No Terceiro Diálogo, o que o espírita responde quando o Padre afirma que a religião já ensina tudo e que a humanidade não precisa de novas luzes espirituais?","option_a":"Se os ensinos tradicionais bastassem na forma como foram interpretados, não haveria tantos incrédulos e materialistas, os quais o Espiritismo reconduz a Deus pela prova experimental.","option_b":"Que a ciência moderna deve abolir toda forma de sentimento religioso.","option_c":"Que o Evangelho de Jesus tornou-se obsoleto diante da filosofia moderna.","option_d":"Que o Espiritismo veio instituir um novo sacerdócio hierárquico na Europa.","option_e":"Que apenas os teólogos podem compreender as leis morais do universo.","correct_option":"A","explanation":"O Espiritismo não vem destruir os princípios fundamentais da religião nem a moral do Cristo, mas combater o materialismo fornecendo provas palpáveis da sobrevivência da alma.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"medio","active":true},{"code":842,"statement":"No diálogo com o Padre, qual é o ponto em que a Doutrina Espírita diverge do dogma teológico das penas eternas e de um inferno material de fogo?","option_a":"O Espiritismo nega que o culpado sofra qualquer consequência após a morte.","option_b":"Os Espíritos ensinam que as penas são morais e proporcionais às faltas, mas nunca perpétuas, pois Deus jamais fecha ao arrependimento a porta da regeneração.","option_c":"A Doutrina Espírita afirma que o sofrimento dura exatamente sete anos para todos os Espíritos.","option_d":"O Espiritismo ensina que os Espíritos criminosos são aniquilados no momento do desencarne.","option_e":"Kardec sustenta que apenas as preces pagas podem libertar uma alma sofredora.","correct_option":"B","explanation":"A condenação irrevogável e eterna é incompatível com a infinita justiça e bondade de Deus; o Espírito culpado sofre nas trevas morais de sua consciência até arrepender-se e reparar o mal por novas provas.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"expert","active":true},{"code":843,"statement":"Segundo o Capítulo II ('Noções elementares de Espiritismo', itens 1 a 8), qual é a grande missão prática do Espiritismo perante o mundo moderno?","option_a":"Substituir as ciências exatas por revelações místicas.","option_b":"Formar uma corporação política para governar as nações.","option_c":"Combater a incredulidade e o materialismo pela prova dos fatos e regenerar a humanidade pela aplicação da moral evangélica.","option_d":"Ensinar processos mágicos para evitar as doenças do corpo físico.","option_e":"Descobrir minas de ouro e pedras preciosas por meio de sonâmbulos.","correct_option":"C","explanation":"Nos itens iniciais do Capítulo II, Kardec destaca que o Espiritismo é o mais poderoso antagonista do materialismo e tem por fim o melhoramento moral da humanidade.","reference":"O Que é o Espiritismo - Cap. II, itens 1 a 8","difficulty":"facil","active":true},{"code":844,"statement":"De acordo com o Capítulo II (itens 13 a 16), de onde os Espíritos tiram o seu envoltório semimaterial denominado perispírito?","option_a":"Dos átomos metálicos do núcleo terrestre.","option_b":"Do oxigênio respirado nos primeiros dias após o nascimento.","option_c":"Da imaginação criadora dos médiuns videntes.","option_d":"Do fluido universal de cada globo, razão pela qual a natureza do perispírito varia conforme o mundo em que o Espírito habita.","option_e":"Da decomposição química dos alimentos ingeridos pelo corpo.","correct_option":"D","explanation":"O Espírito extrai o seu perispírito do fluido cósmico universal próprio de cada mundo; por isso, ao mudar de mundo, muda esse envoltório como quem troca de vestimenta.","reference":"O Que é o Espiritismo - Cap. II, itens 13 a 16","difficulty":"facil","active":true},{"code":845,"statement":"No Capítulo II (itens 17 a 23), ao tratar das diversas ordens de Espíritos, como Allan Kardec sintetiza as três categorias principais da escala espírita?","option_a":"Querubins, Serafins e Arcanjos.","option_b":"Sábios, Guerreiros e Artistas.","option_c":"Visíveis, Invisíveis e Tangíveis.","option_d":"Antigos, Medievais e Modernos.","option_e":"Espíritos imperfeitos (predomínio da matéria sobre o espírito), bons Espíritos (predomínio do espírito sobre a matéria, desejo do bem) e Espíritos puros (perfeição absoluta).","correct_option":"E","explanation":"Embora a transição entre os graus seja insensível, Kardec resume a classificação em Espíritos imperfeitos (inclinados ao mal ou levianos), bons Espíritos e Espíritos puros ou superiores.","reference":"O Que é o Espiritismo - Cap. II, itens 17 a 23","difficulty":"facil","active":true},{"code":846,"statement":"Segundo o Capítulo II (itens 21 e 22), que tipos de Espíritos compõem a classe dos chamados Espíritos levianos, zombeteiros e pseudossábios?","option_a":"Espíritos imperfeitos que, sem serem essencialmente maus, comprazem-se em mistificar, intrigar ou ostentar falso saber com linguagem pomposa.","option_b":"Espíritos puros que testam a paciência dos médiuns por meio de mentiras.","option_c":"Almas de crianças desencarnadas que jamais atingirão a maturidade intelectual.","option_d":"Entidades não humanas criadas exclusivamente para habitar as florestas.","option_e":"Espíritos superiores encarregados de punir os cientistas orgulhosos.","correct_option":"A","explanation":"Nos itens 21 e 22, Kardec descreve os Espíritos levianos, ignorantes e zombeteiros, que se intrometem em tudo e respondem sem saber, bem como os pseudossábios, cheios de orgulho e sistemas falsos.","reference":"O Que é o Espiritismo - Cap. II, itens 21 e 22","difficulty":"expert","active":true},{"code":847,"statement":"Conforme o Capítulo II (itens 25 a 29), qual é a diferença entre manifestações ocultas e manifestações ostensivas dos Espíritos?","option_a":"As ocultas ocorrem apenas à meia-noite e as ostensivas ao meio-dia.","option_b":"As ocultas dão-se pela inspiração invisível no pensamento (sugestões da consciência), enquanto as ostensivas produzem-se por efeitos apreciáveis aos sentidos ou pela mediunidade.","option_c":"As ocultas são sempre produzidas por maus Espíritos e as ostensivas apenas por anjos.","option_d":"As ocultas exigem aparelhos elétricos e as ostensivas dispensam médiuns.","option_e":"Não existe diferença real entre ambas na classificação de Allan Kardec.","correct_option":"B","explanation":"A ação oculta ocorre quando os Espíritos nos inspiram pensamentos e conselhos sem que o percebamos; a ação ostensiva ou patente se dá pela escrita, fala, visão, audição ou fenômenos físicos.","reference":"O Que é o Espiritismo - Cap. II, itens 25 a 29","difficulty":"facil","active":true},{"code":848,"statement":"De acordo com o Capítulo II (itens 30 a 35), que são as manifestações espontâneas e as manifestações provocadas?","option_a":"Espontâneas são as obtidas por médiuns pagos; provocadas são as gratuitas.","option_b":"Espontâneas são as escritas em verso; provocadas são as escritas em prosa.","option_c":"Espontâneas ocorrem sem que ninguém chame o Espírito; provocadas dão-se por meio da evocação ou do concurso intencional dos médiuns.","option_d":"Espontâneas acontecem apenas no sono; provocadas acontecem em vigília.","option_e":"Espontâneas são exclusivas das crianças; provocadas pertencem aos idosos.","correct_option":"C","explanation":"Kardec explica que muitas vezes os Espíritos se manifestam espontaneamente (por ruídos, aparições ou comunicações não solicitadas), mas também podem ser chamados por evocação.","reference":"O Que é o Espiritismo - Cap. II, itens 30 a 35","difficulty":"medio","active":true},{"code":849,"statement":"Segundo o Capítulo II (itens 36 a 39), qual é o fim providencial das manifestações espíritas na atualidade?","option_a":"Satisfazer a curiosidade fútil dos salões mundanos.","option_b":"Substituir a medicina, a engenharia e a jurisprudência.","option_c":"Prever o futuro detalhado de cada indivíduo para livrá-lo de provas.","option_d":"Convencer os homens da existência e imortalidade da alma e da justiça futura, conduzindo-os ao aperfeiçoamento moral.","option_e":"Restaurar os antigos oráculos pagãos da Grécia e do Egito.","correct_option":"D","explanation":"Deus permite as manifestações para esclarecer a humanidade numa época de dúvida, provando que tudo não acaba com a morte do corpo e que colhemos na vida futura o fruto de nossas obras.","reference":"O Que é o Espiritismo - Cap. II, itens 36 a 39","difficulty":"facil","active":true},{"code":850,"statement":"No Capítulo II (itens 40 a 47), como são denominados no Espiritismo os médiuns que escrevem sob a influência dos Espíritos?","option_a":"Médiuns tiptólogos.","option_b":"Médiuns videntes.","option_c":"Médiuns audientes.","option_d":"Médiuns de efeitos físicos.","option_e":"Médiuns escreventes ou psicógrafos.","correct_option":"E","explanation":"No item 45, Allan Kardec define os médiuns escreventes ou psicógrafos como aqueles que têm a faculdade de escrever por si mesmos sob a influência dos Espíritos.","reference":"O Que é o Espiritismo - Cap. II, item 45","difficulty":"facil","active":true},{"code":851,"statement":"Segundo o Capítulo II (itens 46 a 49), qual é a diferença entre os médiuns psicógrafos mecânicos, semimecânicos e intuitivos?","option_a":"No mecânico a mão move-se sem consciência do que escreve; no intuitivo o Espírito atua sobre o pensamento do médium; no semimecânico há impulso na mão acompanhado de consciência das palavras.","option_b":"O mecânico usa máquinas de escrever; o intuitivo usa cestas; o semimecânico usa ardósias.","option_c":"O mecânico só recebe Espíritos inferiores; o intuitivo só recebe Espíritos puros.","option_d":"O mecânico escreve dormindo; o intuitivo escreve em transe cataléptico.","option_e":"Não há distinção alguma entre os três modos de psicografia.","correct_option":"A","explanation":"No médium mecânico o Espírito move diretamente a mão sem que o médium tenha consciência do escrito; no intuitivo transmite o pensamento; no semimecânico participam ambos os mecanismos.","reference":"O Que é o Espiritismo - Cap. II, itens 46 a 49","difficulty":"expert","active":true},{"code":852,"statement":"De acordo com o Capítulo II (itens 41 a 44), como se caracterizam os médiuns de efeitos físicos, os audientes, os falantes e os videntes?","option_a":"São graus hierárquicos de sacerdócio dentro das sociedades espíritas.","option_b":"Pelos diferentes modos de percepção ou ação: produzem fenômenos materiais (ruídos, movimentos), ouvem os Espíritos, falam sob sua ação ou os veem em estado de vigília.","option_c":"São faculdades exclusivas de pessoas que nasceram cegas ou surdas.","option_d":"Referem-se apenas aos fenômenos de sonambulismo provocado por hipnose.","option_e":"Designam médiuns que atuam somente uma vez na vida.","correct_option":"B","explanation":"Kardec classifica as variedades de médiuns segundo os efeitos: efeitos físicos, sensitivos ou impressionáveis, audientes, falantes, videntes, sonâmbulos, curadores, pneumatógrafos e psicógrafos.","reference":"O Que é o Espiritismo - Cap. II, itens 41 a 44","difficulty":"facil","active":true},{"code":853,"statement":"No Capítulo II (item 44), que nome específico Allan Kardec dá à faculdade raríssima de obter a escrita direta traçada pelos próprios Espíritos sem o uso da mão do médium?","option_a":"Tiptologia alfabética.","option_b":"Psicofonia consciente.","option_c":"Pneumatografia (e pneumatofonia para os sons articulados no ar).","option_d":"Clariaudiência intuitiva.","option_e":"Bicorporeidade tangível.","correct_option":"C","explanation":"Kardec denomina pneumatografia a escrita direta produzida pelos Espíritos sem intermediário manual, advertindo também contra as fraudes dos que simulam esse fenômeno.","reference":"O Que é o Espiritismo - Cap. II, item 44","difficulty":"dificil","active":true},{"code":854,"statement":"Segundo o Capítulo II ('Escolhos da mediunidade', itens 55 a 64), qual é o maior perigo que ameaça os médiuns e pode levá-los à obsessão e à perda da assistência dos bons Espíritos?","option_a":"O estudo constante das obras fundamentais da Codificação.","option_b":"A prática gratuita da caridade em benefício dos enfermos.","option_c":"O hábito de fazer preces antes das reuniões mediúnicas.","option_d":"O orgulho, a presunção de infalibilidade e a fascinação exercida por Espíritos enganadores que lisonjeiam a vaidade do médium.","option_e":"A leitura comparada das comunicações em grupos sérios.","correct_option":"D","explanation":"O orgulho é a pedra de toque: quando o médium se julga privilegiado e infalível, afasta os bons Espíritos e entrega-se aos Espíritos mistificadores e fascinadores.","reference":"O Que é o Espiritismo - Cap. II, itens 55 a 64","difficulty":"expert","active":true},{"code":855,"statement":"De acordo com o Capítulo II ('Qualidades dos médiuns', itens 65 a 71), o que atrai os bons Espíritos para junto de um médium?","option_a":"A riqueza material e os títulos acadêmicos do médium.","option_b":"A força física muscular e o temperamento sanguíneo.","option_c":"O uso de talismãs, vestes especiais e incensos.","option_d":"A cobrança de honorários elevados pelas sessões.","option_e":"As qualidades morais do médium: bondade, benevolência, simplicidade de coração, humildade, devotamento e amor ao bem.","correct_option":"E","explanation":"A faculdade mediúnica em si é orgânica e independe da moral, mas o seu bom uso e a assistência dos bons Espíritos dependem essencialmente das qualidades morais do médium.","reference":"O Que é o Espiritismo - Cap. II, itens 65 a 71","difficulty":"facil","active":true},{"code":856,"statement":"No Capítulo II ('Charlatanismo', itens 72 a 81), por que Allan Kardec afirma que o desinteresse material absoluto é a mais segura garantia contra o charlatanismo mediúnico?","option_a":"Porque onde não há lucro nem especulação não há interesse em simular fenômenos, e os Espíritos Superiores não se prestam a exibições mercantis.","option_b":"Porque os Espíritos cobram tributos espirituais em moedas antigas.","option_c":"Porque a lei francesa proibia apenas as reuniões gratuitas.","option_d":"Porque os médiuns gratuitos jamais precisam estudar a Doutrina.","option_e":"Porque o dinheiro destrói quimicamente o fluido magnético humano.","correct_option":"A","explanation":"Os Espíritos não estão à disposição de quem paga; um médium que explorasse sua faculdade precisaria simular fenômenos quando os Espíritos não quisessem comparecer, caindo na fraude.","reference":"O Que é o Espiritismo - Cap. II, itens 72 a 81","difficulty":"expert","active":true},{"code":857,"statement":"Segundo o Capítulo II ('Identidade dos Espíritos', itens 82 a 89), por que não devemos aceitar cegamente os grandes nomes venerados com que certos Espíritos assinam suas comunicações?","option_a":"Porque nenhum Espírito elevado jamais se comunicou com a Terra.","option_b":"Porque Espíritos mistificadores e orgulhosos frequentemente usurpam nomes respeitáveis para impor ideias absurdas ou apócrifas.","option_c":"Porque os Espíritos esquecem todos os nomes próprios após a morte.","option_d":"Porque apenas os Espíritos familiares possuem nome no mundo espiritual.","option_e":"Porque a escrita mediúnica altera automaticamente as letras da assinatura.","correct_option":"B","explanation":"A identidade dos Espíritos antigos ou ilustres não se prova pelo nome assinado, mas pela elevação constante das ideias, pureza moral, ausência de contradições e gravidade da linguagem.","reference":"O Que é o Espiritismo - Cap. II, itens 82 a 89","difficulty":"expert","active":true},{"code":858,"statement":"No Capítulo II ('Contradições', itens 90 a 97), qual é a causa principal das aparentes contradições encontradas em certas comunicações espíritas?","option_a":"A variação climática entre os hemisférios norte e sul.","option_b":"A instabilidade do fluido cósmico universal durante os eclipses.","option_c":"A diversidade de graus de saber e moralidade entre os Espíritos comunicantes, pois cada um fala segundo seus conhecimentos e opiniões pessoais.","option_d":"A falta de dicionários padronizados nas escolas europeias.","option_e":"O defeito de fabricação dos lápis utilizados nas sessões.","correct_option":"C","explanation":"Nem todos os Espíritos sabem tudo: os Espíritos inferiores ou pseudossábios emitem sistemas pessoais e opiniões divergentes, ao passo que os Espíritos Superiores estão sempre de acordo quanto ao ensino moral e fundamental.","reference":"O Que é o Espiritismo - Cap. II, itens 90 a 97","difficulty":"dificil","active":true},{"code":859,"statement":"De acordo com o Capítulo II (itens 95 a 97), que método de controle Allan Kardec estabeleceu para distinguir a verdade do erro no ensino dos Espíritos?","option_a":"Aceitar exclusivamente as comunicações de um único médium parisiense.","option_b":"Submeter todas as mensagens à votação política das câmaras municipais.","option_c":"Rejeitar qualquer comunicação que trate de filosofia ou moral.","option_d":"O controle da razão aliado à concordância universal do ensino dado pelos Espíritos em diferentes lugares por múltiplos médiuns desconhecidos entre si.","option_e":"Realizar sorteios semanais entre as mensagens psicografadas.","correct_option":"D","explanation":"Kardec apoiou a Codificação na concordância geral do ensino dos Espíritos através de numerosos médiuns em diversos países e no exame rigoroso da lógica e do bom senso.","reference":"O Que é o Espiritismo - Cap. II, itens 95 a 97","difficulty":"dificil","active":true},{"code":860,"statement":"Segundo o Capítulo II ('Consequências do Espiritismo', itens 98 a 104), qual é o critério pelo qual se reconhece o verdadeiro espírita?","option_a":"Pela faculdade de mover objetos pesados sem contato físico.","option_b":"Pelo número de livros espíritas que guarda em sua biblioteca.","option_c":"Pelo uso de insígnias exteriores e fórmulas místicas de saudação.","option_d":"Pela capacidade de adivinhar a sorte e o futuro das pessoas.","option_e":"Pela sua transformação moral e pelos esforços que emprega para domar suas más inclinações, praticando a caridade por pensamentos, palavras e obras.","correct_option":"E","explanation":"Crer apenas nos fenômenos faz o crente ou simpatizante; o verdadeiro espírita é o que aplica a moral da Doutrina para reformar-se intimamente e ser mais benevolente e caridoso.","reference":"O Que é o Espiritismo - Cap. II, itens 98 a 104","difficulty":"facil","active":true},{"code":861,"statement":"No início do Capítulo III ('Solução de alguns problemas pela Doutrina Espírita', item 105), o que ensina o Espiritismo sobre a pluralidade dos mundos?","option_a":"Que todos os globos que circulam no espaço são habitados por seres apropriados à constituição física de cada mundo.","option_b":"Que apenas a Terra e Marte possuem seres vivos inteligentes.","option_c":"Que os astros são apenas pontos luminosos criados para enfeitar a noite terrestre.","option_d":"Que os demais planetas só serão habitados após a destruição da Terra.","option_e":"Que a vida espiritual não pode existir fora da atmosfera terrestre.","correct_option":"A","explanation":"No item 105, Kardec expõe que todos os mundos que gravitam no espaço são habitados e apresentam diferentes graus de adiantamento físico e moral.","reference":"O Que é o Espiritismo - Cap. III, item 105","difficulty":"facil","active":true},{"code":862,"statement":"Segundo o Capítulo III (itens 106 e 107), qual é a posição da Terra na hierarquia dos mundos habitados?","option_a":"É o mundo mais atrasado e primitivo de todo o universo.","option_b":"Não está na primeira nem na última linha, mas é um dos mundos menos adiantados, onde ainda predominam as provas, expiações e necessidades materiais.","option_c":"É um mundo celeste onde só habitam Espíritos puros.","option_d":"É o único globo onde existe o livre-arbítrio humano.","option_e":"É um planeta superior a Júpiter em evolução moral e física.","correct_option":"B","explanation":"Kardec esclarece que a Terra não ocupa nem o primeiro nem o último degrau, mas pertence à categoria dos mundos onde a imperfeição moral e as vicissitudes corporais ainda exigem duro trabalho e expiação.","reference":"O Que é o Espiritismo - Cap. III, itens 106 e 107","difficulty":"expert","active":true},{"code":863,"statement":"De acordo com o Capítulo III ('Do homem durante a vida terrestre', itens 108 a 111), em que momento se completa a união definitiva da alma com o corpo?","option_a":"Apenas aos sete anos de idade, quando começa a razão.","option_b":"Três meses após o batismo religioso da criança.","option_c":"Começa na concepção e só é completa no instante do nascimento.","option_d":"Somente quando o jovem atinge a maioridade civil.","option_e":"Apenas no momento da desencarnação do corpo físico.","correct_option":"C","explanation":"No item 110, Kardec precisa que a união da alma com o corpo começa na concepção, mas só se torna completa no momento do nascimento.","reference":"O Que é o Espiritismo - Cap. III, item 110","difficulty":"medio","active":true},{"code":864,"statement":"Segundo o Capítulo III (itens 112 e 113), o que ocorre com a alma durante o sono do corpo físico?","option_a":"A alma adormece profundamente e perde toda a atividade consciente.","option_b":"O perispírito dissolve-se temporariamente até o despertar matinal.","option_c":"O Espírito desencarna definitivamente e outro Espírito ocupa o corpo.","option_d":"Os laços que a prendem ao corpo afrouxam-se e a alma recobra parte de sua liberdade, entrando em relação com outros Espíritos nos sonhos.","option_e":"A alma permanece aprisionada exclusivamente dentro do coração.","correct_option":"D","explanation":"Enquanto o corpo repousa, o Espírito não precisa de descanso: afrouxam-se os laços fluídicos, ele percorre o espaço e comunica-se com encarnados e desencarnados, originando muitas lembranças de sonhos.","reference":"O Que é o Espiritismo - Cap. III, itens 112 e 113","difficulty":"medio","active":true},{"code":865,"statement":"Conforme o Capítulo III ('A alma antes da união com o corpo', itens 114 e 115), como Deus cria todos os Espíritos?","option_a":"Uns já sábios e virtuosos, e outros predestinados ao mal.","option_b":"Dotados desde o primeiro dia de toda a ciência universal.","option_c":"Divididos em castas eternas que jamais se misturam.","option_d":"Formados a partir da divisão da alma dos próprios pais.","option_e":"Simples e ignorantes, isto é, sem ciência e sem conhecimento do bem e do mal, mas com igual aptidão para tudo adquirir pelo esforço próprio.","correct_option":"E","explanation":"Deus, soberanamente justo, não privilegia nenhum Espírito na criação: todos partem do mesmo ponto inicial — simples e ignorantes — e conquistam a perfeição pelo trabalho e livre-arbítrio.","reference":"O Que é o Espiritismo - Cap. III, itens 114 e 115","difficulty":"facil","active":true},{"code":866,"statement":"Segundo o Capítulo III (itens 116 a 119), o que faz o Espírito quando abusa de seu livre-arbítrio e retarda seu adiantamento?","option_a":"Sofre as consequências de suas faltas e precisa recomeçar em novas existências corporais a tarefa que desempenhou mal.","option_b":"É condenado ao fogo eterno sem possibilidade de reparação.","option_c":"Regressa à condição de mineral ou vegetal.","option_d":"Perde a individualidade e dissolve-se no fluido cósmico.","option_e":"Recebe o perdão automático no instante da morte sem precisar progredir.","correct_option":"A","explanation":"Não podendo ir para os mundos felizes sem haver-se depurado, o Espírito estacionário ou culpado reencarna em mundos de provas e expiações para reparar o tempo perdido.","reference":"O Que é o Espiritismo - Cap. III, itens 116 a 119","difficulty":"medio","active":true},{"code":867,"statement":"De acordo com o Capítulo III ('A alma após a morte', itens 120 a 123), a alma conserva a sua individualidade após a morte do corpo?","option_a":"Não, pois mergulha no todo universal como uma gota d'água no oceano.","option_b":"Sim; jamais a perde, conservando a consciência de si mesma e o envoltório etéreo (perispírito), que reproduz a forma humana.","option_c":"Conserva a individualidade apenas durante quarenta dias após o enterro.","option_d":"Somente os grandes gênios mantêm a memória individual após a morte.","option_e":"A alma divide-se em várias centelhas inconscientes.","correct_option":"B","explanation":"Sem individualidade e consciência de si mesma, a sobrevivência seria equivalente ao nada; o Espírito leva consigo o perispírito, sua memória, seus afetos, suas luzes ou sua ignorância.","reference":"O Que é o Espiritismo - Cap. III, itens 120 a 123","difficulty":"facil","active":true},{"code":868,"statement":"Segundo o Capítulo III (itens 124 a 127), de que depende a duração e a intensidade da perturbação que se segue à morte?","option_a":"Da riqueza do mausoléu construído pela família na Terra.","option_b":"Da idade cronológica do corpo físico no instante do óbito.","option_c":"Da elevação moral do Espírito e do seu grau de desapego das coisas materiais.","option_d":"Da estação do ano e da fase da Lua no dia do desencarne.","option_e":"Do número de velas acesas ao redor do féretro.","correct_option":"C","explanation":"Para o homem de consciência pura, que já se desligou dos interesses terrenos durante a vida, o despertar espiritual é rápido e calmo; para o materialista e o culpado, a perturbação é longa e penosa.","reference":"O Que é o Espiritismo - Cap. III, itens 124 a 127","difficulty":"expert","active":true},{"code":869,"statement":"No Capítulo III ('Estado dos Espíritos', itens 128 a 132), como são chamados os Espíritos que se encontram no intervalo entre duas existências corporais?","option_a":"Espíritos elementais.","option_b":"Espíritos cristalizados.","option_c":"Espíritos incriados.","option_d":"Espíritos errantes (no estado de erraticidade).","option_e":"Espíritos anônimos.","correct_option":"D","explanation":"No item 128, Kardec explica que no intervalo de suas existências corporais os Espíritos estão no estado de erraticidade e são denominados Espíritos errantes.","reference":"O Que é o Espiritismo - Cap. III, item 128","difficulty":"facil","active":true},{"code":870,"statement":"De acordo com o Capítulo III (itens 129 e 130), todos os Espíritos desencarnados permanecem errantes indefinidamente?","option_a":"Sim, todos os Espíritos continuam errantes por toda a eternidade.","option_b":"Sim, pois nenhum Espírito jamais fica livre da reencarnação.","option_c":"Não, porque após três séculos os Espíritos deixam de existir.","option_d":"Apenas os Espíritos inferiores deixam de ser errantes.","option_e":"Não; os Espíritos puros, que atingiram a perfeição e não precisam mais de novas reencarnações, não são mais errantes, pois seu estado é definitivo.","correct_option":"E","explanation":"O estado errante é transitório e próprio dos Espíritos que ainda têm de reencarnar para progredir; os Espíritos puros já chegaram ao termo da escala e gozam da felicidade definitiva.","reference":"O Que é o Espiritismo - Cap. III, itens 129 e 130","difficulty":"medio","active":true},{"code":871,"statement":"Segundo o Capítulo III ('Penas e gozos futuros', itens 133 a 137), qual é a natureza das penas e das alegrias da alma na vida espiritual?","option_a":"São essencialmente morais e inerentes ao grau de elevação ou de imperfeição do próprio Espírito, que carrega em si mesmo o seu céu ou o seu inferno.","option_b":"Consistem em torturas físicas produzidas por caldeiras e chamas materiais.","option_c":"Resumem-se na contemplação imóvel e ociosa sem qualquer atividade útil.","option_d":"Dependem exclusivamente da posição social que o indivíduo ocupou na Terra.","option_e":"São iguais para todos os Espíritos, independentemente de suas obras.","correct_option":"A","explanation":"Não tendo mais corpo carnal, o Espírito não sofre torturas físicas exteriores: a felicidade nasce da pureza, do amor e das missões úteis, enquanto o sofrimento decorre do remorso, das paixões não saciadas e da visão de suas vítimas.","reference":"O Que é o Espiritismo - Cap. III, itens 133 a 137","difficulty":"dificil","active":true},{"code":872,"statement":"Conforme o Capítulo III (item 136), onde estão localizados o céu e o inferno segundo a Doutrina Espírita?","option_a":"O céu fica acima das estrelas fixas e o inferno no centro incandescente da Terra.","option_b":"Em toda parte: o céu está onde há Espíritos felizes e mundos superiores; o inferno está no próprio íntimo dos Espíritos imperfeitos e nos mundos de expiação.","option_c":"O céu localiza-se no Sol e o inferno na superfície da Lua.","option_d":"Ambos são lugares circunscritos cercados por muralhas intransponíveis.","option_e":"Existem apenas como figuras poéticas sem correspondência com o estado da alma.","correct_option":"B","explanation":"O céu e o inferno não são lugares geograficamente circunscritos: o Espírito feliz leva consigo a ventura onde quer que esteja, e o Espírito perverso ou impenitente carrega em si mesmo o seu tormento.","reference":"O Que é o Espiritismo - Cap. III, item 136","difficulty":"medio","active":true},{"code":873,"statement":"De acordo com o Capítulo III (item 137), a que corresponde na Doutrina Espírita a ideia tradicional do purgatório?","option_a":"A um vale escuro onde as almas aguardam passivamente o fim do mundo.","option_b":"A uma prisão subterrânea onde se paga resgate em moedas.","option_c":"Ao estado de erraticidade dolorosa e às encarnações corporais expiatórias em que o Espírito se depura de suas imperfeições.","option_d":"Ao sono letárgico dos Espíritos que desencarnaram na infância.","option_e":"À perda temporária da inteligência nos mundos inferiores.","correct_option":"C","explanation":"Kardec explica no item 137 que o purgatório é uma realidade moral: consiste nas dores da erraticidade e nas existências terrestres de prova e expiação pelas quais nos purificamos.","reference":"O Que é o Espiritismo - Cap. III, item 137","difficulty":"facil","active":true},{"code":874,"statement":"Segundo o Capítulo III ('Intervenção dos Espíritos no mundo corporal', itens 138 a 143), o que é o Espírito protetor ou Anjo de guarda?","option_a":"Um Espírito inferior encarregado de vigiar os bens materiais da família.","option_b":"Uma força magnética impessoal gerada pelo pensamento humano.","option_c":"Um Espírito que anula o livre-arbítrio do protegido para impedi-lo de errar.","option_d":"Um Espírito de ordem elevada ligado ao indivíduo desde o nascimento para guiá-lo no caminho do bem por meio de bons conselhos.","option_e":"Apenas uma figura alegórica sem existência real no plano espiritual.","correct_option":"D","explanation":"Todo homem tem um Espírito protetor (anjo guardião ou bom gênio) de natureza superior, que o assiste com inspirações salutares sem jamais suprimir o seu livre-arbítrio.","reference":"O Que é o Espiritismo - Cap. III, itens 140 e 141","difficulty":"facil","active":true},{"code":875,"statement":"De acordo com o Capítulo III (itens 142 e 143), qual é o meio mais eficaz de afastar os maus Espíritos e atrair a assistência dos bons?","option_a":"Pronunciar fórmulas latinas de exorcismo e queimar ervas aromáticas.","option_b":"Traçar sinais cabalísticos nas portas e janelas da residência.","option_c":"Evitar qualquer conversa sobre assuntos espirituais ou filosóficos.","option_d":"Portar amuletos metálicos magnetizados por sonâmbulos.","option_e":"Praticar o bem, confiar em Deus, elevar o pensamento pela prece sincera e vencer as próprias imperfeições morais.","correct_option":"E","explanation":"Os maus Espíritos são atraídos pelas nossas próprias paixões (orgulho, egoísmo, ódio, cobiça); nenhuma fórmula exterior os afasta se o homem não se reformar moralmente.","reference":"O Que é o Espiritismo - Cap. III, itens 142 e 143","difficulty":"facil","active":true},{"code":876,"statement":"Segundo o Capítulo III ('Causas anteriores das aflições', itens 144 a 148), onde reside a causa da maioria das aflições terrenas?","option_a":"Na própria conduta imprudente, orgulhosa ou egoísta do homem na vida presente; e, quando não têm causa atual, nas faltas cometidas em existências anteriores.","option_b":"Na fatalidade cega do destino contra a qual o homem nada pode fazer.","option_c":"No pecado original cometido por um único casal no início dos tempos.","option_d":"Na influência maléfica dos cometas sobre a atmosfera terrestre.","option_e":"No capricho arbitrário da Providência ao distribuir dores sem motivo.","correct_option":"A","explanation":"Kardec distingue duas fontes de aflições: 1ª as que o homem cria nesta própria vida por sua imprevidência e más paixões; 2ª as que atingem o homem de bem sem causa atual aparente, que são expiações de vidas passadas.","reference":"O Que é o Espiritismo - Cap. III, itens 144 a 148","difficulty":"expert","active":true},{"code":877,"statement":"No Capítulo III (itens 146 a 148), por que a justiça divina exige que a falta cometida em uma existência seja reparada por uma expiação equivalente?","option_a":"Porque Deus sente prazer em vingar-se das criaturas que erraram.","option_b":"Porque cada Espírito é solidário com o seu próprio passado, e a expiação ensina pela experiência da dor aquilo que ele fez outros sofrerem.","option_c":"Porque os Espíritos Superiores cobram tributos proporcionais a cada erro.","option_d":"Porque o arrependimento sincero não tem nenhum valor perante as leis morais.","option_e":"Porque somente o sofrimento físico cria a inteligência no Espírito.","correct_option":"B","explanation":"Quem abusou da riqueza, do poder ou da saúde aprende, passando pelas provas contrárias, a corrigir o orgulho e a desenvolver a humildade e a caridade.","reference":"O Que é o Espiritismo - Cap. III, itens 146 a 148","difficulty":"dificil","active":true},{"code":878,"statement":"Segundo o Capítulo III ('Esquecimento do passado', itens 149 a 152), por que Deus concedeu ao homem encarnado o esquecimento temporário de suas existências anteriores?","option_a":"Para impedir que a humanidade progrida nas ciências e nas artes.","option_b":"Porque o cérebro material não possui espaço físico para guardar lembranças.","option_c":"Porque a lembrança precisa das faltas e inimizades passadas humilharia o homem, perturbaria as relações sociais e entravaria o seu livre-arbítrio.","option_d":"Porque o perispírito apaga definitivamente toda a história do Espírito.","option_e":"Para que ninguém possa jamais acreditar na pluralidade das existências.","correct_option":"C","explanation":"O esquecimento temporário durante a vida corpórea é um benefício da sabedoria divina: evita vergonhas paralisantes e ódios perpétuos, permitindo que antigos adversários se reconciliem na mesma família.","reference":"O Que é o Espiritismo - Cap. III, itens 149 a 152","difficulty":"facil","active":true},{"code":879,"statement":"De acordo com o Capítulo III (itens 151 e 152), embora não tenhamos a lembrança detalhada dos fatos de vidas passadas, o que nos resta delas durante a existência atual?","option_a":"Apenas marcas físicas de nascença na pele.","option_b":"O conhecimento exato do idioma que falamos na encarnação anterior.","option_c":"A memória completa dos nomes e datas de todas as nossas famílias passadas.","option_d":"As tendências instintivas, as aptidões inatas e a voz da consciência, que nos adverte contra os erros já sofridos.","option_e":"Absolutamente nada, nem mesmo no campo intelectual ou moral.","correct_option":"D","explanation":"Esquecemos os fatos particulares, mas conservamos o resultado da experiência adquirida sob a forma de ideias inatas, aptidões precoces e intuições morais.","reference":"O Que é o Espiritismo - Cap. III, itens 151 e 152","difficulty":"expert","active":true},{"code":880,"statement":"Segundo o Capítulo III (itens 153 e 154), como a Doutrina Espírita explica as simpatias e antipatias espontâneas entre pessoas que parecem ver-se pela primeira vez?","option_a":"Pela coincidência da cor dos olhos e do timbre da voz.","option_b":"Pela ação exclusiva da temperatura ambiente no sistema nervoso.","option_c":"Por um sorteio aleatório realizado antes do nascimento.","option_d":"Pela diferença de nacionalidade e de classe financeira.","option_e":"Pela intuição vaga de relações anteriores de afeição ou de animosidade que os Espíritos tiveram em existências passadas ou na erraticidade.","correct_option":"E","explanation":"Dois Espíritos que se conheceram — como amigos dedicados ou como inimigos — pressentem-se ao se reencontrarem na carne, gerando simpatia imediata ou repulsão instintiva que o dever moral manda vencer.","reference":"O Que é o Espiritismo - Cap. III, itens 153 e 154","difficulty":"expert","active":true},{"code":881,"statement":"No Capítulo III ('Suicídio', itens 155 a 157), qual é o ensinamento constante de todos os Espíritos sobre o suicídio?","option_a":"O homem nunca tem o direito de dispor da própria vida; o suicídio é sempre uma transgressão da lei de Deus que agrava os sofrimentos do Espírito.","option_b":"O suicídio é permitido quando a pessoa sofre de doença física incurável.","option_c":"O suicida alcança imediatamente o repouso e o esquecimento de suas dores.","option_d":"O suicídio apressa a evolução espiritual quando motivado por desgosto amoroso.","option_e":"A alma do suicida desintegra-se no instante em que o coração para de bater.","correct_option":"A","explanation":"Nos itens 155 a 157, Kardec registra que o suicida procura fugir de um sofrimento passageiro e cai em torturas morais e perispirituais muito mais longas e terríveis.","reference":"O Que é o Espiritismo - Cap. III, itens 155 a 157","difficulty":"facil","active":true},{"code":882,"statement":"Segundo o Capítulo III (item 156), por que o suicida sente por longo tempo após a morte todas as angústias e impressões da agonia física?","option_a":"Porque o corpo material continua respirando dentro do túmulo.","option_b":"Porque na morte violenta provocada antes do termo natural os laços entre o perispírito e o corpo estavam cheios de vitalidade e só se rompem lentamente.","option_c":"Porque os bons Espíritos recusam-se a ouvir qualquer prece em favor dele.","option_d":"Porque ele perde para sempre a capacidade de arrepender-se.","option_e":"Porque o fluido cósmico congela-se ao redor do local do sepultamento.","correct_option":"B","explanation":"Na morte natural a vida orgânica extingue-se pouco a pouco e o desprendimento é suave; no suicídio os laços vitais são quebrados à força em plena vitalidade, repercutindo dolorosamente no perispírito.","reference":"O Que é o Espiritismo - Cap. III, item 156","difficulty":"expert","active":true},{"code":883,"statement":"De acordo com o Capítulo III ('Loucura, idiotia', itens 158 a 162), o Espírito do louco ou do idiota de nascença é uma alma inferior ou privada de inteligência?","option_a":"Sim, é uma alma criada sem o princípio da razão humana.","option_b":"Sim, trata-se do espírito de um animal encarnado por engano em corpo humano.","option_c":"Não; o Espírito em si pode ser inteligente, mas acha-se impedido de manifestar seu pensamento pela imperfeição ou lesão dos órgãos cerebrais que lhe servem de instrumento.","option_d":"Não possui alma própria, vivendo apenas pela vida vegetativa do corpo.","option_e":"Perdeu definitivamente a memória e a consciência por toda a eternidade.","correct_option":"C","explanation":"O cérebro é o instrumento de manifestação do pensamento na vida corpórea: assim como o mais hábil músico não pode tirar sons harmoniosos de um instrumento quebrado, o Espírito fica tolhido por órgãos imperfeitos.","reference":"O Que é o Espiritismo - Cap. III, itens 158 a 162","difficulty":"dificil","active":true},{"code":884,"statement":"Segundo o Capítulo III (itens 160 a 162), com que finalidade moral e educativa um Espírito inteligente pode ser submetido à dura prova da idiotia ou da loucura?","option_a":"Por mero acidente biológico sem qualquer relação com a justiça de Deus.","option_b":"Para premiar os Espíritos que já atingiram a santidade suprema.","option_c":"Para demonstrar que a matéria governa soberanamente o destino da alma.","option_d":"Como expiação do abuso que fez de sua inteligência, de seu orgulho ou de suas paixões em existência anterior, sofrendo o constrangimento de não poder exprimir-se.","option_e":"Para isentar a família de qualquer dever de caridade e assistência.","correct_option":"D","explanation":"No corpo do idiota o Espírito tem consciência interior de sua situação e sofre o constrangimento de não poder comunicar-se, expiando assim o abuso anterior de suas faculdades intelectuais.","reference":"O Que é o Espiritismo - Cap. III, itens 160 a 162","difficulty":"dificil","active":true},{"code":885,"statement":"Na Biografia de Allan Kardec por Henri Sausse, qual memória premiada em 1831 pela Academia Real de Ciências de Arras o jovem professor Rivail escreveu?","option_a":"Um tratado sobre a aplicação da eletricidade aos telégrafos marítimos.","option_b":"Um estudo astronômico sobre as órbitas dos cometas periódicos.","option_c":"Uma tese médica sobre o tratamento da febre amarela nas colônias.","option_d":"Um romance histórico sobre os druidas da antiga Gália.","option_e":"'Qual o sistema de estudos mais em harmonia com as necessidades da época?'.","correct_option":"E","explanation":"Henri Sausse destaca que em 1831 a Academia Real de Ciências de Arras premiou a notável memória pedagógica de Rivail sobre a reforma do ensino público na França.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":886,"statement":"Segundo Henri Sausse, que resposta memorável deu o professor Rivail em 1854 quando o Sr. Fortier lhe disse que as mesas falavam ao serem interrogadas?","option_a":"'Só acreditarei quando o vir e quando me provarem que uma mesa tem cérebro para pensar, nervos para sentir e que possa tornar-se sonâmbula; até lá, permita que eu não veja nisso mais que um conto para fazer dormir em pé.'","option_b":"'Aceito imediatamente o prodígio, pois tudo no universo é sobrenatural e miraculoso.'","option_c":"'Jamais assistirei a uma sessão, porque a ciência oficial já proibiu tais estudos.'","option_d":"'As mesas falam porque são habitadas pelos gênios elementais da floresta.'","option_e":"'Publicarei amanhã mesmo um livro confirmando essas revelações sem precisar verificá-las.'","correct_option":"A","explanation":"Essa resposta célebre mostra a prudência e o rigor científico de Rivail: ele não negou a possibilidade de uma força desconhecida, mas exigiu observação direta e explicação racional antes de admitir uma causa inteligente.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"dificil","active":true},{"code":887,"statement":"Conforme relata Henri Sausse na Biografia, qual era o nome do Espírito protetor de Allan Kardec, que se comunicou com ele pela médium Srta. Aline C. em 1856 confirmando sua missão?","option_a":"O Espírito de São Luís.","option_b":"O Espírito da Verdade (e também o seu Espírito familiar Zéfiro nas reuniões da família Baudin).","option_c":"O Espírito de Emanuel Swedenborg.","option_d":"O Espírito de Galileu Galilei.","option_e":"O Espírito de Joana d'Arc.","correct_option":"B","explanation":"Nas sessões da família Baudin manifestava-se o Espírito protetor Zéfiro (que lhe revelou o nome Allan Kardec), e em 1856 o Espírito da Verdade confirmou-lhe a árdua missão de codificar a Doutrina.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"medio","active":true},{"code":888,"statement":"Segundo a Biografia escrita por Henri Sausse, em que cidade espanhola ocorreu em 9 de outubro de 1861 o célebre auto de fé em que foram queimados trezentos volumes espíritas?","option_a":"Em Madri.","option_b":"Em Sevilha.","option_c":"Em Barcelona.","option_d":"Em Valência.","option_e":"Em Salamanca.","correct_option":"C","explanation":"Em 9 de outubro de 1861, por ordem do bispo de Barcelona, foram queimados em praça pública trezentos volumes e brochuras espíritas, fato que repercutiu imensamente a favor da divulgação do Espiritismo.","reference":"O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)","difficulty":"dificil","active":true},{"code":889,"statement":"No Segundo Diálogo ('O Cético'), como o espírita explica por que a Ciência oficial não é competente para julgar a priori a questão dos Espíritos?","option_a":"Porque todos os cientistas são inimigos declarados do progresso humano.","option_b":"Porque a matemática e a física são ciências falsas e ilusórias.","option_c":"Porque o Espiritismo proíbe que médicos e físicos estudem suas obras.","option_d":"Porque as ciências exatas tratam apenas das leis da matéria bruta, enquanto o Espiritismo estuda o elemento espiritual e suas relações com a matéria, o que escapa aos instrumentos de laboratório.","option_e":"Porque os Espíritos apagam a memória dos cientistas que entram nas reuniões.","correct_option":"D","explanation":"Cada ciência tem a sua especialidade: a química e a física estudam a matéria inerte; querer submeter o Espírito livre ao cadinho ou ao bisturi é sair do objeto próprio das ciências materiais.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"expert","active":true},{"code":890,"statement":"No Segundo Diálogo, quando o Cético pergunta se o médium sente o pensamento do Espírito antes de escrever, o que Kardec esclarece?","option_a":"Nunca; o médium fica sempre inconsciente como uma estátua de pedra.","option_b":"Sempre; não existe nenhum médium que escreva sem saber antes toda a frase.","option_c":"Apenas quando o Espírito comunicante é um parente próximo desencarnado.","option_d":"Somente nas noites de tempestade elétrica.","option_e":"Isso depende do tipo de mediunidade: no médium mecânico a mão escreve sem que ele tenha consciência; no médium intuitivo ou semimecânico o pensamento atravessa o seu cérebro no ato da escrita.","correct_option":"E","explanation":"Kardec explica ao Cético a distinção entre o médium puramente passivo ou mecânico e o médium intuitivo ou semimecânico, mostrando como em ambos os casos se comprova a independência da ideia comunicada.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"medio","active":true},{"code":891,"statement":"No Segundo Diálogo ('O Cético'), como Allan Kardec explica o fenômeno das aparições visíveis e até tangíveis (agêneres) de Espíritos?","option_a":"Pela condensação momentânea do fluido perispiritual combinada ao fluido emitido por um médium de efeitos físicos, tornando o perispírito visível e por vezes palpável.","option_b":"Pela ressurreição definitiva da carne e dos ossos que estavam no cemitério.","option_c":"Por simples ilusão de óptica causada por espelhos côncavos nas salas.","option_d":"Pela transformação química do oxigênio do ar em tecido muscular permanente.","option_e":"Pelo desdobramento exclusivo dos animais domésticos presentes na casa.","correct_option":"A","explanation":"Em estado normal o perispírito é invisível para os nossos olhos materiais, mas por uma modificação molecular e combinação com o fluido de certos médiuns pode condensar-se até tornar-se visível e momentaneamente tangível.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"dificil","active":true},{"code":892,"statement":"No Segundo Diálogo, por que Allan Kardec afirma que no Espiritismo não há nada de sobrenatural nem de maravilhoso?","option_a":"Porque o Espiritismo nega a existência de Deus e da alma imortal.","option_b":"Porque todos os fenômenos espíritas repousam sobre leis da Natureza até então desconhecidas; uma vez conhecida a lei que os rege, o maravilhoso desaparece.","option_c":"Porque todas as manifestações mediúnicas são meros truques de prestidigitação.","option_d":"Porque os Espíritos são feitos de matéria sólida idêntica ao ferro.","option_e":"Porque a Ciência já conhecia o perispírito desde a antiguidade clássica.","correct_option":"B","explanation":"Deus não derroga as próprias leis que estabeleceu; o que parecia sobrenatural ou miraculoso na ignorância das leis fluídicas e espirituais entra na ordem dos fenômenos naturais explicados pelo Espiritismo.","reference":"O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético","difficulty":"facil","active":true},{"code":893,"statement":"No Terceiro Diálogo ('O Padre'), como o espírita responde à pergunta sobre se o Espiritismo é uma nova religião?","option_a":"Afirmando que o Espiritismo tem bispos, dogmas fechados e sacramentos próprios.","option_b":"Dizendo que o Espiritismo proíbe seus adeptos de entrarem em qualquer igreja.","option_c":"Explicando que o Espiritismo é uma ciência de observação e uma doutrina filosófica de consequências morais que não possui culto material, sacerdócio nem templos, proclamando a liberdade de consciência.","option_d":"Declarando que o Espiritismo exige o batismo obrigatório nas águas do rio Sena.","option_e":"Sustentando que a moral espírita é oposta ao ensino de Jesus Cristo.","correct_option":"C","explanation":"Em O Que é o Espiritismo, Kardec esclarece ao Padre que o Espiritismo não se constitui como igreja com sacerdócio ou rituais exteriores, mas acolhe homens de todas as crenças na vivência da caridade cristã.","reference":"O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre","difficulty":"dificil","active":true},{"code":894,"statement":"Segundo o Capítulo II (itens 31 a 34), todos os Espíritos que são evocados podem atender imediatamente ao chamado?","option_a":"Sim, qualquer Espírito é obrigado a comparecer no instante em que seu nome é pronunciado.","option_b":"Não, porque nenhum Espírito pode jamais ouvir o pensamento dos encarnados.","option_c":"Sim, desde que o evocador pronuncie o nome do Espírito três vezes em voz alta.","option_d":"Não; o Espírito pode estar reencarnado ou ocupado em missão distante, ou a permissão pode ser-lhe negada; nesse caso, ou avisa que não pode vir, ou um Espírito amigo responde por ele.","option_e":"Apenas os Espíritos sofredores têm permissão de atender às evocações.","correct_option":"D","explanation":"Kardec explica nos itens 32 a 34 que diversas causas podem impedir a comunicação imediata de um Espírito evocado, inclusive o fato de achar-se reencarnado na Terra ou em outro mundo.","reference":"O Que é o Espiritismo - Cap. II, itens 31 a 34","difficulty":"expert","active":true},{"code":895,"statement":"No Capítulo II (itens 50 a 54), o que recomenda Allan Kardec àquele que deseja verificar experimentalmente se possui a faculdade de médium escrevente (psicógrafo)?","option_a":"Submeter-se antes a um jejum rigoroso de sete dias no escuro.","option_b":"Comprar aparelhos magnéticos de cobre e cristal.","option_c":"Ingerir substâncias narcóticas para provocar o transe.","option_d":"Exigir que os Espíritos movam os móveis da sala como sinal prévio.","option_e":"Recolher-se em silêncio com fé, elevar o pensamento em prece ao seu Espírito protetor e aguardar com paciência e perseverança, renovando a tentativa por vários dias sem desanimar.","correct_option":"E","explanation":"Nos itens 50 a 54, Kardec ensina que o meio de tentar é simples: recolhimento, prece sincera ao anjo guardião e aos bons Espíritos, evitando perguntas frívolas ou interesseiras e perseverando com calma.","reference":"O Que é o Espiritismo - Cap. II, itens 50 a 54","difficulty":"medio","active":true},{"code":896,"statement":"Segundo o Capítulo II (itens 57 a 62), quais são os sinais característicos pelos quais se reconhece a obsessão e a fascinação mediúnica?","option_a":"A exigência do Espírito de que o médium se isole, rejeite todo exame crítico alheio, escreva incessantemente coisas pueris ou absurdas e acredite cegamente em sua própria infalibilidade.","option_b":"O conselho constante para estudar, praticar a caridade e submeter os escritos ao crivo da razão.","option_c":"A raridade das comunicações e a brevidade das respostas morais.","option_d":"A recomendação de respeitar os deveres familiares e profissionais.","option_e":"O estímulo à humildade, à paciência e ao perdão das ofensas.","correct_option":"A","explanation":"Todo Espírito que receia o exame e a discussão, que isola o médium dos conselhos prudentes, que impõe ordens ridículas ou lisonjeia o orgulho é infalivelmente um Espírito mistificador e obsessor.","reference":"O Que é o Espiritismo - Cap. II, itens 57 a 62","difficulty":"dificil","active":true},{"code":897,"statement":"De acordo com o Capítulo III (itens 108 e 109), a alma existe antes da formação do corpo físico que vai animar?","option_a":"Não; a alma é criada no exato instante em que o recém-nascido respira.","option_b":"Sim; a alma preexiste à união com o corpo, pois é um Espírito que já viveu na erraticidade e em existências anteriores.","option_c":"Apenas as almas dos profetas preexistiam ao nascimento.","option_d":"Não, porque a alma é uma secreção produzida pelo cérebro infantil.","option_e":"Somente nos planetas superiores a alma existe antes do corpo.","correct_option":"B","explanation":"No item 109, Kardec afirma categoricamente a preexistência da alma: antes de unir-se ao corpo, ela é um dos Espíritos que povoam o mundo invisível e que se encarna para progredir.","reference":"O Que é o Espiritismo - Cap. III, itens 108 e 109","difficulty":"medio","active":true},{"code":898,"statement":"Segundo o Capítulo III (itens 122 e 125), como se dá a separação entre a alma e o corpo no momento da morte?","option_a":"De forma sempre instantânea e acompanhada de dores físicas lancinantes para todos os homens.","option_b":"Somente após a decomposição total dos ossos no sepulcro.","option_c":"Gradualmente, desatando-se os laços fluídicos do perispírito sem dor maior do que na vida; para o justo, a separação é pronta e suave como o despertar de um sono.","option_d":"Mediante o rompimento mecânico da coluna vertebral.","option_e":"Apenas quando o sol se põe no horizonte local.","correct_option":"C","explanation":"No item 122, Kardec explica que a separação não é brusca nem dolorosa em si mesma: o corpo frequentemente sofre mais durante a vida e a moléstia do que no momento do desprendimento final.","reference":"O Que é o Espiritismo - Cap. III, itens 122 e 125","difficulty":"expert","active":true},{"code":899,"statement":"Conforme o Capítulo III (itens 131 e 132), o que fazem os Espíritos durante o estado de erraticidade?","option_a":"Dormem em letargia profunda até o momento de reencarnar.","option_b":"Ficam presos imóvelmente ao redor do próprio túmulo.","option_c":"Perdem o livre-arbítrio e tornam-se autômatos inconscientes.","option_d":"Refletem sobre a existência passada, instruem-se, procuram meios de se adiantar e escolhem novas provas para as futuras encarnações.","option_e":"Dedicam-se exclusivamente a produzir ruídos materiais nas casas.","correct_option":"D","explanation":"Na erraticidade, o Espírito esclarecido estuda o seu passado, reconhece seus erros, frequenta centros de instrução espiritual e prepara as provas que lhe permitirão avançar em nova existência.","reference":"O Que é o Espiritismo - Cap. III, itens 131 e 132","difficulty":"facil","active":true},{"code":900,"statement":"Na conclusão de 'O Que é o Espiritismo', qual é a síntese prática de toda a moral ensinada pelos Espíritos Superiores?","option_a":"O isolamento absoluto do mundo social e a renúncia ao trabalho.","option_b":"A busca do poder terreno e da supremacia intelectual sobre os semelhantes.","option_c":"A observância exclusiva de cerimônias exteriores sem reforma íntima.","option_d":"O fatalismo resignado que dispensa o esforço de aperfeiçoamento.","option_e":"O amor a Deus acima de tudo e a caridade para com o próximo — benevolência para com todos, indulgência para as imperfeições alheias e perdão das ofensas.","correct_option":"E","explanation":"Toda a filosofia moral de O Que é o Espiritismo converge para a máxima evangélica da caridade ativa, da fraternidade e da reforma íntima como condição indispensável da felicidade futura.","reference":"O Que é o Espiritismo - Cap. II, itens 98 a 104 / Cap. III","difficulty":"facil","active":true}]$questions$::jsonb) AS q(
  code integer, statement text, option_a text, option_b text, option_c text,
  option_d text, option_e text, correct_option text, explanation text,
  reference text, difficulty text, active boolean
)
ON CONFLICT (statement) DO NOTHING;

COMMIT;

-- Conferência: deve retornar 100 se nenhuma questão já existia no banco.
SELECT book, COUNT(*) AS total
FROM public.questions
WHERE book='o_que_e_espiritismo'
GROUP BY book;
